SELECT analytics_order_facts.channel, SUM(analytics_order_facts.contribution_margin) AS contribution_margin FROM analytics_order_facts WHERE analytics_order_facts.year IN (2026, 2022) AND analytics_order_facts.region = 'East' AND analytics_order_facts.customer_segment = 'public' AND analytics_order_facts.payment_method = 'debit' GROUP BY analytics_order_facts.channel ORDER BY analytics_order_facts.channel ASC LIMIT 24
